    image_patch = ImagePatch(image)
    cows = image_patch.find("cow")
    houses = image_patch.find("house")
    if not cows or not houses: 
        return image_patch
    house_depths = {house: house.compute_depth() for house in houses}
    nearest_house = min(house_depths, key=house_depths.get)
    nearest_cows = [cow for cow in cows if is_near(cow, nearest_house)]
    return nearest_cows[0] if nearest_cows else cows[0]

def is_near(a: ImagePatch, b: ImagePatch, margin: float = 0.0) -> bool:
    return abs(distance(a, b)) <= margin

